INSERT INTO TBEP_PLANTILLAS (NOMBRE,TITULO,CUERPO,UID_USUARIO)
VALUES ('Plantilla para la apertura de una plaza ofertada', 'Plaza ofertada abierta  <<idplaza>> - <<area>>', '<p>Estimado/a candidato/a, conforme a lo establecido en el art&iacute;culo 19 del Reglamento para la<br />sustituci&oacute;n del PDI de la Universidad de Ja&eacute;n, le informamos que en la web de la Bolsa de Empleo de<br />la Universidad de Ja&eacute;n se ha publicado una oferta de contrataci&oacute;n para la categor&iacute;a de profesor<br />sustituto interino con c&oacute;digo &lt;&lt;idplaza&gt;&gt; en el &aacute;rea de conocimiento &lt;&lt;area&gt;&gt; en la que Usted ha<br />sido baremado/a.</p><p>Datos de la Oferta de contrataci&oacute;n con categor&iacute;a de Profesor Sustituto Interino:</p><ul><li>C&oacute;digo: &lt;&lt;idplaza&gt;&gt;</li><li>&Aacute;rea: &lt;&lt;area&gt;&gt;</li><li>Causa Contrataci&oacute;n: &lt;&lt;justificacion&gt;&gt;</li><li>Duraci&oacute;n: &lt;&lt;duracion_prevista&gt;&gt;</li><li>Horario: &lt;&lt;horario&gt;&gt;</li><li>Dedicaci&oacute;n: &lt;&lt;dedicacion&gt;&gt;</li><li>Cuatrimestre: &lt;&lt;cuatrimestre&gt;&gt;</li><li>Sueldo: &lt;&lt;sueldo&gt;&gt; euros brutos mensuales</li><li>Centro de Destino: &lt;&lt;centro_destino&gt;&gt;</li></ul><p>Si est&aacute; interesado/a en la misma, debe acceder a la citada bolsa para indicar que S&Iacute; est&aacute;<br />interesado/a. En este caso, no significa que vaya a ser contratado para la misma, sino que de todas<br />las personas candidatas del &aacute;rea, seleccionaremos en orden de puntuaci&oacute;n a aquellas que hayan<br />mostrado su voluntad de aceptar la plaza ofertada.<br />La plaza ofertada estar&aacute; disponible para manifestar su inter&eacute;s en la participaci&oacute;n hasta las<br />&lt;&lt;hora_fin_oferta&gt;&gt; del d&iacute;a &lt;&lt;fecha_fin_oferta&gt;&gt;.</p><p><strong>Nota</strong>: Estos datos son meramente informativos, careciendo de vinculaci&oacute;n jur&iacute;dica para la<br />Universidad de Ja&eacute;n</p>', 'CARGA_INICIAL');
--/////////////////////
INSERT INTO TBEP_PLANTILLAS (NOMBRE,TITULO,CUERPO,UID_USUARIO)
VALUES ('Plantilla para la cita contratación', 'Cita para contratación  PSI - <<idplaza>> - <<area>> - <<apellidos_candidato>> <<nombre_candidato>> <<NIF_candidato>> <<email_candidato>>', '<pre>Nos ponemos en contacto con Vd. al objeto de iniciar el proceso de contrataci&oacute;n<br />como profesor/a sustituto/a interino/a, ya que es la primera persona candidata<br />disponible de la plaza que se detalla a continuaci&oacute;n, por lo que es muy importante<br />que lea atentamente este correo y siga sus instrucciones:<br />- &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Plaza: &lt;&lt;idplaza&gt;&gt;<br />- &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&Aacute;rea: &lt;&lt;area&gt;&gt;<br />Habiendo surgido necesidades docentes de contrataci&oacute;n en dicha &aacute;rea le<br />comunicamos que, en aplicaci&oacute;n de los art&iacute;culos 19 y 20 del Reglamento para la<br />sustituci&oacute;n del PDI de la Universidad de Ja&eacute;n, deber&aacute; personarse en el Servicio de<br />Personal a las &lt;&lt;hora_cita&gt;&gt; del &lt;&lt;fecha_cita&gt;&gt; junto con la siguiente<br />documentaci&oacute;n para la firma del contrato laboral de PSI:<br />1. Titulaci&oacute;n acad&eacute;mica que da acceso a la plaza (solamente se le requerir&aacute; si no<br />consta en su expediente).<br />2. DNI (solamente se le requerir&aacute; si no consta en su expediente).<br />3. Datos bancarios. (solamente se le requerir&aacute; si no constan en su expediente o<br />quiere modificarlos).<br />4. Comunicaci&oacute;n de datos al pagador.<br />5. N&uacute;mero de afiliaci&oacute;n a la Seguridad Social (solamente se le requerir&aacute; si no<br />consta en su expediente).<br />6. Certificado M&eacute;dico (lo podr&aacute; entregar el d&iacute;a de la firma del contrato).<br />7. Tarjeta Sanitaria (solamente se le requerir&aacute; si no consta en su expediente).<br />8. Anexo I o solicitud de compatibilidad.<br />9. Anexo de toma de datos (solamente se le requerir&aacute; si no consta en su<br />expediente o quiere modificarlo).<br />IMPORTANTE: Esta documentaci&oacute;n la podr&aacute; adelantar respondiendo a este correo<br />electr&oacute;nico. Del mismo modo, en el supuesto de haberle ofrecido m&aacute;s de una plaza,<br />deber&aacute; indicar en su respuesta el orden de prioridad de las plazas ofrecidas.<br />Si no est&aacute; interesado/a en la plaza que se le ha otorgado y en consecuencia<br />subscribir contrato laboral con esta Universidad, nos lo deber&aacute; indicar al objeto de<br />facilitar la contrataci&oacute;n del sustituto/a correspondiente. Para ello debe comunicar la<br />renuncia correspondiente a la siguiente direcci&oacute;n de correo secpdi@ujaen.es.<br />Le recordamos que, en el supuesto de no realizar la aceptaci&oacute;n de la plaza o plazas<br />ofertadas en el plazo indicado, se entender&aacute; que renuncia a las mismas.<br />Un saludo,</pre>', 'CARGA_INICIAL');
--/////////////////////
INSERT INTO TBEP_PLANTILLAS (NOMBRE,TITULO,CUERPO,UID_USUARIO)
VALUES ('Plantilla para el cierre de la plaza', 'Cierre de la plaza  PSI - <<idplaza>> - <<area>>', '<p>Se informa que se ha procedido al cierre de la plaza, que a continuaci&oacute;n se detalla, con la<br />contrataci&oacute;n de D/D&ordf;. &lt;&lt;nombre_candidato&gt;&gt; &lt;&lt;apellidos_candidato&gt;&gt;:<br />Categor&iacute;a: PSI<br />Plaza: &lt;&lt;idplaza&gt;&gt;<br />&Aacute;rea: &lt;&lt;area&gt;&gt;<br />Causa Contrataci&oacute;n: &lt;&lt;justificacion&gt;&gt;<br />Duraci&oacute;n: &lt;&lt;duracion_prevista&gt;&gt;<br />Dedicaci&oacute;n: &lt;&lt;dedicacion&gt;&gt;<br />Cuatrimestre: &lt;&lt;cuatrimestre&gt;&gt;<br />Centro de Destino: &lt;&lt;centro_destino&gt;&gt;</p><p>Saludos</p>', 'CARGA_INICIAL');
--/////////////////////
INSERT INTO TBEP_PLANTILLAS (NOMBRE,TITULO,CUERPO,UID_USUARIO)
VALUES ('Plantilla para la aprobación de la plaza', 'Aprobación de la plaza  <<idplaza>> - <<area>>', '<!DOCTYPE html><html><head></head><body><p>Estimado &lt;&lt;nombre, apellidos&gt;&gt;, conforme a lo establecido en el art&iacute;culo 9.2 del Reglamento de sustituci&oacute;n del PDI de la Universidad de Ja&eacute;n, te informo que se ha aprobado, en base a la solicitud que realizaste el pasado &lt;&lt;fecha_creacion&gt;&gt;, la contrataci&oacute;n extraordinaria de PSI con las siguientes caracter&iacute;sticas:</p><p>Datos de la contrataci&oacute;n extraordinaria:</p><ul><li><strong>Idplaza</strong>: &lt;&lt;idplaza&gt;&gt;</li><li><strong>Fecha de creaci&oacute;n</strong>: &lt;&lt;fecha_creacion&gt;&gt;</li><li><strong>Fecha de aprobaci&oacute;n</strong>: &lt;&lt;fecha_aprobacion&gt;&gt;</li><li><strong>&Aacute;rea</strong>: &lt;&lt;area&gt;&gt;</li><li><strong>Justificaci&oacute;n</strong>: &lt;&lt;justificacion&gt;&gt;</li><li><strong>Asignaturas</strong>: &lt;&lt;horario&gt;&gt;</li><li><strong>Centro de Destino</strong>: &lt;&lt;centro_destino&gt;&gt;</li></ul><p>&nbsp;</p><p>Adem&aacute;s, te informo que he dado traslado al Servicio de Personal para que tramite el procedimiento de contrataci&oacute;n extraordinaria. No obstante, mientras se resuelve dicha contrataci&oacute;n extraordinaria, recordarte que el Departamento arbitrar&aacute; las medidas necesarias para garantizar que la docencia sea impartida atendiendo a lo dispuesto en el art&iacute;culo 6 del Reglamento.</p><p>&nbsp;</p><p>Atentamente,</p><p>El Director del Secretariado de Profesorado.</p></body></html>', 'CARGA_INICIAL');
--/////////////////////
INSERT INTO TBEP_PLANTILLAS (NOMBRE,TITULO,CUERPO,UID_USUARIO)
VALUES ('Plantilla para la creación de una plaza ofertada', 'Creación de la plaza  <<idplaza>> - <<area>>', '<!DOCTYPE html><html><head></head><body><div class="comment-container"><div class="action-comment can-view-video markeddown js-comment" dir="auto"><div class="current-comment js-friendly-links js-open-card"><p>Estimado Vicerrector de Profesorado y Ordenaci&oacute;n Acad&eacute;mica, conforme a lo establecido en el art&iacute;culo 9 del Reglamento de sustituci&oacute;n del PDI de la Universidad de Ja&eacute;n, te informo que he realizado una petici&oacute;n para que se cubra mediante una contrataci&oacute;n extraordinaria la siguiente necesidad que no puede ser atendida por el profesorado del Departamento:</p><p>Datos de la petici&oacute;n para la contrataci&oacute;n extraordinaria:</p><ul><li><strong>Idplaza</strong>: &lt;&lt;idplaza&gt;&gt;</li><li><strong>Peticionario</strong>: &lt;&lt;nombre_apellidos&gt;&gt; (del usuario que crea la plaza)</li><li><strong>Fecha de creaci&oacute;n</strong>: &lt;&lt;fecha_creacion&gt;&gt;</li><li><strong>&Aacute;rea</strong>: &lt;&lt;area&gt;&gt;</li><li><strong>Justificaci&oacute;n</strong>: &lt;&lt;justificacion&gt;&gt;</li><li><strong>Asignaturas</strong>: &lt;&lt;horario&gt;&gt;</li><li><strong>Centro de Destino</strong>: &lt;&lt;centro_destino&gt;&gt;</li></ul><p>Atentamente.</p></div></div></div></body></html>', 'CARGA_INICIAL');